  "docstring": "Services controller idle/sleep conditions by draining pending Bluetooth events and polling timer/status hardware for idle transitions.",
  "subsystem": "hal",
  "var_renames": {
    "result": "status",
    "v1": "ctx",
    "v9": "start_tick",
    "v10": "elapsed_ticks",
    "v11": "poll_start_tick",
    "v14": "poll_elapsed_ticks",
    "v15": "masked_status"
  },
  "struct_hints": [
    {
      "offset": 4,
      "meaning": "idle request/status flag, bit 0 tested and cleared"
    },
    {
      "offset": 72,
      "meaning": "pending HCI LE event indicator"
    },
    {
      "offset": 128,
      "meaning": "controller/device mode byte used in idle logging and mode tests"
    },
    {
      "offset": 1224,
      "meaning": "pending Bluetooth connection flush flag"
    }
  ]
}
